import React from "react";
import "./Photos.css";

export default function Photos(props) {
  console.log(props.photos);
  if (props.photos) {
    return (
      <div className="row">
        <div className="col">
          <section className="Photos">
            {props.photos.map(function (photo, index) {
              return <img src={photo.src.tiny} key={index}></img>;
            })}
          </section>
        </div>
      </div>
    );
  } else {
    return null;
  }
}
